/**
 * `<openapps-buy>` — pick a package, pick a rail, pay, get credits.
 *
 * The three rails look different to the user but share one shape: start the
 * top-up, then watch its status. Nothing here decides whether a payment
 * succeeded — the server does that from a webhook, a chain log, or a
 * Lightning settlement, and this element only polls `waitFor`.
 */
import { css, html, nothing, type TemplateResult } from "lit";
import { customElement, property, state } from "lit/decorators.js";
import type { CreditPackage, Packages, Topup, Usdt0Network } from "@openapps/sdk";

import { OpenAppsElement } from "./base.js";
import { notify } from "./context.js";
import { formatNumber, t } from "./catalogue.js";

type Rail = "stripe" | "ethereum" | "lightning" | "usdt0";

/** What the user must do to pay, once a top-up has been created. */
type Instruction =
  | { kind: "redirect" }
  | {
      kind: "address";
      chain: string;
      address: string;
      amount: number;
      /**
       * Set for USD₮0: the one token and network this address credits, and
       * the issuer-freezable notice that has to travel with it. Absent for
       * the Ethereum rail, whose copy is unchanged.
       */
      usdt0?: { token: string; networkName: string; notice: string };
    }
  | { kind: "invoice"; bolt11: string; amountMsat: number };

/**
 * Shown wherever USD₮ is offered, if the server sent no wording of its own.
 * Kept short: the point is that the payer learns it before paying, not a
 * disclosure they scroll past.
 */
const USDT0_FREEZABLE_FALLBACK =
  "USD₮0 is issued by Tether, which can freeze any address holding it.";

@customElement("openapps-buy")
export class OpenAppsBuy extends OpenAppsElement {
  /** Restrict the offered rails, e.g. `rails="lightning,stripe"`. */
  @property({ type: String }) rails = "";

  /**
   * Where Stripe returns the browser after checkout.
   *
   * Empty (the default) comes back to this page, which is what a web app
   * wants. `none` ends on the server's own confirmation page instead — for
   * a host that cannot be redirected to at all, which is every browser
   * extension: Chrome refuses to land a cross-origin redirect on a
   * `chrome-extension://` page. Anything else is used verbatim.
   *
   * Without this, an extension had to hand-roll its own Stripe button and
   * restrict this element to the other rails, which is how one payment
   * surface turns into two that look nothing alike.
   */
  @property({ type: String, attribute: "return-to" }) returnTo = "";

  @state() private packages: Packages | null = null;
  @state() private selected: CreditPackage | null = null;
  @state() private instruction: Instruction | null = null;
  @state() private topup: Topup | null = null;
  @state() private waiting = false;

  #abort?: AbortController;

  override connectedCallback(): void {
    super.connectedCallback();
    void this.load();
  }

  override disconnectedCallback(): void {
    // Leaving the page must not keep a poll loop alive.
    this.#abort?.abort();
    super.disconnectedCallback();
  }

  protected override onSessionChange(): void {
    // A notify may be the configure() that finally supplied a client, so a
    // load that could not run before has to be retried. Re-rendering alone
    // would leave the element on "Loading packages…" forever, because the
    // fetch it is waiting for never happened.
    if (!this.packages) {
      void this.load();
      return;
    }
    this.requestUpdate();
  }

  private async load(): Promise<void> {
    // The element upgrades the moment the bundle defines it, which on a
    // plain HTML page is before the host script calls configure(). There is
    // nothing to fetch yet, and reporting "no OpenApps client" here would
    // latch a message into `error` that outlives the condition and that a
    // user cannot act on anyway.
    if (!this.sdkOrNull) return;
    const packages = await this.run(() => this.sdk.payments.packages());
    if (packages) this.packages = packages;
  }

  /** Rails the server has enabled, intersected with the `rails` attribute. */
  private get offeredRails(): Rail[] {
    if (!this.packages) return [];
    const enabled = (["stripe", "ethereum", "lightning", "usdt0"] as Rail[]).filter(
      (rail) => this.packages?.rails?.[rail] === true,
    )
      // USD₮0 is offered per network; with none listed there is nothing to
      // press, so the rail is as good as off.
      .filter((rail) => rail !== "usdt0" || this.usdt0Networks.length > 0);
    const allowed = this.rails
      .split(",")
      .map((r) => r.trim())
      .filter(Boolean);
    return allowed.length ? enabled.filter((r) => allowed.includes(r)) : enabled;
  }

  /** The USD₮0 networks the server lists. Empty unless it enabled them. */
  private get usdt0Networks(): Usdt0Network[] {
    const networks = this.packages?.usdt0?.networks;
    return Array.isArray(networks) ? networks : [];
  }

  private get usdt0Notice(): string {
    return this.packages?.usdt0?.notice || USDT0_FREEZABLE_FALLBACK;
  }

  private async start(rail: Rail, network?: Usdt0Network): Promise<void> {
    const pkg = this.selected;
    if (!pkg) return;

    await this.run(async () => {
      let topupId: string;
      switch (rail) {
        case "stripe": {
          // `none` means "do not try to come back here"; empty means the
          // SDK's default of this page.
          const checkout = await this.sdk.payments.stripeCheckout(pkg.id, {
            returnTo: this.returnTo === "none" ? null : this.returnTo || undefined,
          });
          this.instruction = { kind: "redirect" };
          // Stripe hosts the card form; we hand the browser over and the
          // webhook credits the account whether or not the user comes back.
          //
          // Cancelable, so a host that must not navigate its own window —
          // an extension page, which is destroyed the moment it does — can
          // open the URL its own way instead. Everyone else gets the
          // navigation by doing nothing.
          const handled = !this.dispatchEvent(
            new CustomEvent("openapps-checkout", {
              detail: { url: checkout.checkout_url, packageId: pkg.id },
              cancelable: true,
              bubbles: true,
              composed: true,
            }),
          );
          if (!handled) window.location.href = checkout.checkout_url;
          return;
        }
        case "ethereum": {
          const deposit = await this.sdk.payments.ethDepositAddress(pkg.id);
          topupId = deposit.topup_id;
          this.instruction = {
            kind: "address",
            chain: deposit.chain,
            address: deposit.address,
            amount: deposit.expected_amount,
          };
          break;
        }
        case "usdt0": {
          if (!network) return;
          const deposit = await this.sdk.payments.usdt0DepositAddress(pkg.id, network.id);
          topupId = deposit.topup_id;
          this.instruction = {
            kind: "address",
            chain: deposit.chain,
            address: deposit.address,
            amount: deposit.expected_amount,
            usdt0: {
              token: deposit.token?.symbol || "USD₮0",
              networkName: deposit.network_name || network.name,
              notice: deposit.notice || this.usdt0Notice,
            },
          };
          break;
        }
        case "lightning": {
          const invoice = await this.sdk.payments.lightningInvoice(pkg.id);
          topupId = invoice.topup_id;
          this.instruction = {
            kind: "invoice",
            bolt11: invoice.bolt11,
            amountMsat: invoice.amount_msat,
          };
          break;
        }
      }
      void this.watch(topupId, WAIT_TIMEOUT_MS[rail]);
    });
  }

  private async watch(topupId: string, timeoutMs?: number): Promise<void> {
    this.#abort?.abort();
    const controller = new AbortController();
    this.#abort = controller;
    this.waiting = true;
    try {
      const topup = await this.sdk.payments.waitFor(topupId, {
        timeoutMs,
        signal: controller.signal,
        onPoll: (t) => {
          this.topup = t;
        },
      });
      this.topup = topup;
      if (topup.status === "confirmed") {
        this.emit("openapps-topup", topup);
        // Tells every other element on the page (the balance, typically)
        // that its data is stale.
        notify();
      }
    } catch (cause) {
      if (!(cause instanceof Error && cause.name === "AbortError")) {
        this.error = describeWait(cause);
      }
    } finally {
      this.waiting = false;
    }
  }

  private reset(): void {
    this.#abort?.abort();
    this.selected = null;
    this.instruction = null;
    this.topup = null;
    this.error = null;
  }

  override render(): TemplateResult {
    // No client configured yet; configure() will notify and re-render.
    if (!this.sdkOrNull) return html`<p class="muted">${t("Loading…")}</p>`;
    if (!this.sdk.isLoggedIn) {
      return html`<p class="muted">${t("Sign in to buy credits.")}</p>`;
    }
    if (!this.packages) {
      return html`<p class="muted">${this.error ?? t("Loading packages…")}</p>`;
    }
    if (this.instruction) return this.renderInstruction(this.instruction);
    if (this.selected) return this.renderRails(this.selected);
    // A malformed or partial response must degrade to "nothing to buy",
    // never to a blank element from a render-time crash.
    return this.renderPackages(this.packages.packages ?? []);
  }

  private renderPackages(packages: CreditPackage[]): TemplateResult {
    if (packages.length === 0) {
      return html`<p class="muted">${t("No credit packages are configured.")}</p>`;
    }
    return html`
      <div class="grid">
        ${packages.map(
          (pkg) => html`
            <button class="package" @click=${() => (this.selected = pkg)}>
              <span class="credits">
                ${t("{n} credits", { n: pkg.credits })}
              </span>
              <span class="perunit caption">${perCreditCost(pkg)}</span>
              <span class="price">${formatUsd(pkg.usd_price)}</span>
            </button>
          `,
        )}
      </div>
      ${this.error ? html`<p class="error" role="alert">${this.error}</p>` : nothing}
    `;
  }

  private renderRails(pkg: CreditPackage): TemplateResult {
    const rails = this.offeredRails;
    return html`
      <p>
        <strong>${t("{n} credits", { n: pkg.credits })}</strong> —
        ${formatUsd(pkg.usd_price)}
      </p>
      <div class="stack">
        ${rails.map((rail) =>
          rail === "usdt0"
            ? this.renderUsdt0Options()
            : html`
                <button class="primary" ?disabled=${this.busy} @click=${() => this.start(rail)}>
                  ${t(RAIL_LABELS[rail])}
                </button>
              `,
        )}
        ${rails.length === 0
          ? html`<p class="muted">${t("No payment methods are enabled.")}</p>`
          : nothing}
        <button @click=${this.reset}>${t("Back")}</button>
      </div>
      ${this.error ? html`<p class="error" role="alert">${this.error}</p>` : nothing}
    `;
  }

  /**
   * One "Pay with USD₮" button per network, and the freeze notice once
   * beneath them. Per network rather than one button and a picker after:
   * sending on the wrong chain is the expensive mistake here, so the chain
   * is chosen in the same act as the rail.
   */
  private renderUsdt0Options(): TemplateResult {
    return html`
      <div class="usdt0" role="group" aria-label="Pay with USD₮">
        ${this.usdt0Networks.map(
          (network) => html`
            <button
              class="primary"
              ?disabled=${this.busy}
              @click=${() => this.start("usdt0", network)}
            >
              ${RAIL_LABELS.usdt0} on ${network.name}
            </button>
          `,
        )}
        <p class="caption freezable">
          <strong>Issuer-freezable.</strong> ${this.usdt0Notice}
        </p>
      </div>
    `;
  }

  private renderInstruction(instruction: Instruction): TemplateResult {
    const status = this.topup?.status ?? "pending";
    if (status === "confirmed") {
      return html`
        <span class="badge success"><span class="dot"></span>${t("Confirmed")}</span>
        <p class="ok">${t("Payment confirmed — credits added.")}</p>
        <button @click=${this.reset}>${t("Buy more")}</button>
      `;
    }
    if (status === "failed" || status === "expired") {
      return html`
        <span class="badge danger"><span class="dot"></span>${status === "failed" ? t("Failed") : t("Expired")}</span>
        <p class="error" role="alert">${status === "failed" ? t("This top-up failed. Nothing was charged.") : t("This top-up expired. Nothing was charged.")}</p>
        <button @click=${this.reset}>${t("Try again")}</button>
      `;
    }

    return html`
      ${instruction.kind === "redirect"
        ? html`<p class="muted">${t("Redirecting to checkout…")}</p>`
        : nothing}
      ${instruction.kind === "address" && instruction.usdt0
        ? html`
            <p>Send exactly <strong>${formatUnits(instruction.amount, 6)}</strong>
            ${instruction.usdt0.token} on <strong>${instruction.usdt0.networkName}</strong>
            to:</p>
            <code class="payload">${instruction.address}</code>
            <p class="caption">
              Only ${instruction.usdt0.token} on ${instruction.usdt0.networkName} is credited
              to this address; other tokens or networks are not.
            </p>
            <p class="caption freezable">
              <strong>Issuer-freezable.</strong> ${instruction.usdt0.notice}
            </p>
          `
        : nothing}
      ${instruction.kind === "address" && !instruction.usdt0
        ? html`
            <p>${t("Send exactly")} <strong>${formatUnits(instruction.amount, 6)}</strong> ${t("USDC or USDT on")}
            <code>${instruction.chain}</code> ${t("to:")}</p>
            <code class="payload">${instruction.address}</code>
          `
        : nothing}
      ${instruction.kind === "invoice"
        ? html`
            <p>${t("Pay this Lightning invoice")}
            (<strong>${t("{n} sats", { n: Math.ceil(instruction.amountMsat / 1000) })}</strong>):</p>
            <code class="payload">${instruction.bolt11}</code>
          `
        : nothing}
      ${instruction.kind !== "redirect"
        ? html`
            <div class="row">
              <button @click=${() => this.copy(payloadOf(instruction))}>${t("Copy")}</button>
              <button @click=${this.reset}>${t("Cancel")}</button>
            </div>
            ${this.renderWaiting()}
          `
        : nothing}
      ${this.error ? html`<p class="error" role="alert">${this.error}</p>` : nothing}
    `;
  }

  /**
   * What to say while a payment settles.
   *
   * An on-chain deposit is credited only once it is deep enough, which is
   * minutes. Through all of that the payer has already sent their money, so
   * an unchanging "Waiting for payment…" reads as though it was lost — and
   * the natural response to that is to pay again. Once the server has seen
   * the deposit it reports how deep it is, and a number that visibly climbs
   * is the difference between waiting and worrying.
   */
  private renderWaiting(): TemplateResult {
    if (!this.waiting) {
      return html`<p class="muted" aria-live="polite">${t("Not watching for payment.")}</p>`;
    }
    const seen = this.topup?.confirmations;
    // Nothing matching has appeared on chain yet — including the whole
    // Stripe and Lightning case, where confirmations never apply.
    if (seen === undefined) {
      return html`<p class="muted" aria-live="polite">${t("Waiting for payment…")}</p>`;
    }
    const required = this.topup?.confirmations_required;
    // Finality is not a block count, so there is no honest fraction to
    // show; that the deposit was seen at all is the reassuring part.
    if (required == null) {
      return html`
        <p class="muted" aria-live="polite">
          ${t("Payment received — waiting for the network to finalise it.")}
        </p>
      `;
    }
    // Confirmations keep climbing after the requirement is met, but a bar
    // reading "14 of 12" looks like a bug rather than success.
    const done = Math.min(seen, required);
    return html`
      <p class="muted" aria-live="polite">
        ${t("Payment received — confirming ({done} of {required}).", {
          done: String(done),
          required: String(required),
        })}
      </p>
      <progress
        class="confirms"
        max=${required}
        value=${done}
        aria-label=${t("Confirmations")}
      ></progress>
    `;
  }

  private async copy(text: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      this.error = t("Could not copy — select the text and copy it manually.");
    }
  }

  static override styles = [
    OpenAppsElement.baseStyles,
    css`
      /* Packs stack as rows rather than tiles: the numbers line up down the
         right edge, which is what makes three prices comparable at a glance. */
      .grid {
        display: grid;
        gap: 8px;
      }
      .package {
        display: flex;
        align-items: center;
        gap: 14px;
        min-height: auto;
        padding: 14px 16px;
        text-align: left;
        border-radius: var(--radius-lg, 12px);
      }
      .package:hover:not([disabled]) {
        border-color: var(--border-strong, var(--fb-hairline));
      }
      .credits {
        flex: 1;
        font: var(--weight-medium, 500) var(--text-base, 15px) / 1.2
          var(--font-sans, "Geist", system-ui, sans-serif);
        color: var(--text-strong, var(--fb-strong));
      }
      /* Money is always mono — balances, prices, per-unit rates, ledger
         amounts. Tabular figures keep the column aligned across packs. */
      .price {
        font-family: var(--font-mono, "Geist Mono", ui-monospace, monospace);
        font-variant-numeric: tabular-nums;
        font-size: var(--text-md, 17px);
        color: var(--text-strong, var(--fb-strong));
      }
      .perunit {
        font-family: var(--font-mono, "Geist Mono", ui-monospace, monospace);
        font-size: var(--text-2xs, 11px);
        color: var(--text-faint, var(--fb-faint));
      }
      .stack {
        display: flex;
        flex-direction: column;
        gap: 0.5em;
      }
      .row {
        display: flex;
        gap: 0.5em;
        margin-top: 0.5em;
      }
      .ok {
        font-weight: 600;
      }
      .usdt0 {
        display: flex;
        flex-direction: column;
        gap: 0.5em;
      }
      .freezable {
        margin: 0;
        color: var(--text-muted, var(--fb-muted));
      }
      .confirms {
        display: block;
        width: 100%;
        height: 0.4em;
        margin-top: 0.35em;
        border: none;
        border-radius: 999px;
        overflow: hidden;
        background: var(--surface-card, var(--fb-card));
        accent-color: var(--brand, var(--fb-brand));
      }
      /* WebKit ignores accent-color on <progress>, so colour it directly. */
      .confirms::-webkit-progress-bar {
        background: var(--surface-card, var(--fb-card));
      }
      .confirms::-webkit-progress-value {
        background: var(--brand, var(--fb-brand));
      }
    `,
  ];
}

const RAIL_LABELS: Record<Rail, string> = {
  stripe: "Pay by card",
  ethereum: "Pay with USDC / USDT",
  lightning: "Pay with Lightning",
  usdt0: "Pay with USD₮",
};

/**
 * How long to keep watching a top-up, per rail. `undefined` keeps the SDK's
 * 15-minute default.
 *
 * Ethereum credits only at the `finalized` tag, and finality is slower than
 * it first looks: an epoch is 6.4 minutes, and a block finalises two epochs
 * after the one containing it, so a transaction landing early in an epoch
 * can take ~19 minutes. Against the default the UI would stop watching a
 * payment that is merely still settling — the watcher credits it either
 * way, but the page would have already said it gave up. Stripe and
 * Lightning confirm in seconds and need no extension.
 */
const WAIT_TIMEOUT_MS: Record<Rail, number | undefined> = {
  stripe: undefined,
  lightning: undefined,
  ethereum: 30 * 60 * 1000,
  // Arbitrum credits at L1 finality, ~15–25 minutes after the transfer;
  // Plasma and Stable in seconds. One budget covers the slowest.
  usdt0: 40 * 60 * 1000,
};

function payloadOf(instruction: Instruction): string {
  if (instruction.kind === "address") return instruction.address;
  if (instruction.kind === "invoice") return instruction.bolt11;
  return "";
}

/** USD minor units → "$10.00" (in Russian "10,00 $", in German "10,00 $"). */
export function formatUsd(cents: number): string {
  return formatNumber(cents / 100, { style: "currency", currency: "USD" });
}

/**
 * Unit price, as "0.45¢ each".
 *
 * Three packs at three prices are not comparable by inspection — the whole
 * point of a larger pack is a lower unit cost, and that is the one number
 * the prices themselves do not show. Two decimals below a cent, one above,
 * so a realistic range stays readable without implying false precision.
 */
export function perCreditCost(pkg: CreditPackage): string {
  if (pkg.credits <= 0) return "";
  const cents = pkg.usd_price / pkg.credits;
  const digits = cents < 1 ? 2 : 1;
  // Written here rather than by t(): t() would write a number with as many
  // decimals as it has, and "0.5¢" next to "0.45¢" does not compare.
  return t("{cents}¢ each", {
    cents: formatNumber(cents, { minimumFractionDigits: digits, maximumFractionDigits: digits }),
  });
}

/**
 * Token minor units → a decimal number, trailing zeros trimmed, in the
 * interface's language ("0.5" in English, "0,5" in Russian). Not grouped:
 * it is the exact amount to send, read off and typed into a wallet.
 */
export function formatUnits(amount: number, decimals: number): string {
  return formatNumber(amount / 10 ** decimals, {
    maximumFractionDigits: decimals,
    useGrouping: false,
  });
}

/** A timed-out wait is not a failed payment, and must not read like one. */
function describeWait(cause: unknown): string {
  const message = cause instanceof Error ? cause.message : String(cause);
  return message.includes("still pending")
    ? t("Still waiting on the network. Your credits will appear once the payment settles.")
    : message;
}

declare global {
  interface HTMLElementTagNameMap {
    "openapps-buy": OpenAppsBuy;
  }
}
